export type ShipmentStatus = 'Pending' | 'In Transit' | 'Delivered' | 'Failed' | 'Returned';
export type DriverStatus = 'Active' | 'Offline' | 'On Trip';
export type VehicleStatus = 'Available' | 'On Trip' | 'Maintenance' | 'Inactive';

export interface Shipment {
  id: string;
  waybill: string;
  customer: string;
  customerPhone: string;
  origin: string;
  destination: string;
  status: ShipmentStatus;
  driver: string;
  driverId: string;
  amount: number;
  isCOD: boolean;
  codCollected: boolean;
  weight: number;
  date: string;
  estimatedDelivery: string;
  description: string;
  timeline: TrackingEvent[];
}

export interface TrackingEvent {
  status: string;
  location: string;
  time: string;
  completed: boolean;
}

export interface Driver {
  id: string;
  name: string;
  phone: string;
  email: string;
  vehicleType: string;
  vehiclePlate: string;
  status: DriverStatus;
  todayDeliveries: number;
  totalDeliveries: number;
  rating: number;
  joinDate: string;
  avatar: string;
  earnings: number;
}

export interface Vehicle {
  id: string;
  plate: string;
  type: string;
  driver: string;
  driverId: string;
  status: VehicleStatus;
  lastService: string;
  nextService: string;
  mileage: number;
  year: number;
  model: string;
  fuel: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  address: string;
  city: string;
  totalShipments: number;
  totalSpent: number;
  lastShipment: string;
  type: 'Individual' | 'Business';
}

export interface RevenueData {
  date: string;
  revenue: number;
  shipments: number;
  cod: number;
}

